def compute_order_amount(on_hand_inventory, pipeline_orders, last_demand, quoted_lead_time):
    target = 108.76563768503814  # OPT_PARAM: {"initial": 108.76563768503814, "min": 100.0, "max": 400.0, "type": "float"}
    demand_sensitivity = 0.0  # OPT_PARAM: {"initial": 0.0, "min": 0.0, "max": 1.5, "type": "float"}
    pipeline_sensitivity = 0.1  # OPT_PARAM: {"initial": 0.1, "min": 0.0, "max": 0.5, "type": "float"}
    demand_impact = 0.0  # OPT_PARAM: {"initial": 0.0, "min": 0.0, "max": 2.0, "type": "float"}

    adjusted_target = target + demand_sensitivity * last_demand
    inventory_position = on_hand_inventory + sum(pipeline_orders)
    demand_adjusted = last_demand * demand_impact
    order_amount = max(0.0, adjusted_target - inventory_position * pipeline_sensitivity + demand_adjusted)
    return order_amount
